mapper.select:
select sol.module_type, sol.business_id, sol.create_time, max(sol.create_user_name) as create_user_name, array_to_string(array_agg(DISTINCT sol.operation),',') as operation, array_to_string(array_agg(DISTINCT sol.content),';') as content from operate_log sol
AND sol.business_id = #{params.businessId}
AND sol.pid = #{params.pid}
and ( sol.content ILIKE concat('%',#{params.searchKey}::text,'%') or sol.operation ILIKE concat('%',#{params.searchKey}::text,'%') or sol.create_user_name ILIKE concat('%',#{params.searchKey}::text,'%') )
group by sol.module_type,sol.business_id,sol.create_time order by sol.create_time desc
